#!/usr/bin/env Rscript
## flexyBayes validation study -- build driver (generated by the validation scaffold).
##
## Run from the report/ directory with PV_ENGINE set to the validation engine
## directory (kept out of this file so it stays path-free and publishable):
##   PV_ENGINE=<engine-dir> Rscript build.R smoke   # source engine + smoke profile
##   PV_ENGINE=<engine-dir> Rscript build.R bench    # re-run every battery bench
##   PV_ENGINE=<engine-dir> Rscript build.R render   # render documents from caches
##   PV_ENGINE=<engine-dir> Rscript build.R full     # bench then render
mode <- if (length(commandArgs(TRUE))) commandArgs(TRUE)[1] else "smoke"
stopifnot(dir.exists("bench"), file.exists("cards.yaml"))   # run from report/

## Engine directory -- read from the environment so this file stays path-free and
## publishable (the skill path is never hard-coded). Set PV_ENGINE before running.
eng <- Sys.getenv("PV_ENGINE")
if (!nzchar(eng))
  stop("set PV_ENGINE to the validation engine directory before running build.R",
       call. = FALSE)
for (f in c("theme.R", "setup.R", "run_bench.R", "assemble.R", "gates.R",
            "build_explorer.R", "conformance.R", "crosslang.R", "schematic.R",
            "audit_docs.R"))
  source(file.path(eng, f))

## Load the package under study from source so the bench phase exercises the
## working tree, never a stale installed copy.
suppressMessages(
  devtools::load_all(normalizePath(file.path("..", "flexyBayes")), quiet = TRUE)
)
title <- "flexyBayes: validation and benchmark study"

if (mode == "smoke") {
  source("bench/contract-smoke.R")
  conf <- readRDS("bench/results/contract-conformance.rds")
  ok <- pv_conformance_gate(conf)
  cat(sprintf("conformance gate: %s\n", if (isTRUE(ok)) "PASS" else "FINDINGS"))
  quit(save = "no", status = if (isTRUE(ok)) 0L else 0L)  # findings are informative on a scaffold
}

battery <- setdiff(sort(list.files("bench", pattern = "\\.R$")),
                   c("run_all.R", "contract-conformance.R"))
if (mode %in% c("bench", "full"))
  for (b in battery) { cat("bench:", b, "\n"); source(file.path("bench", b)) }
if (mode %in% c("render", "full")) {
  rd <- normalizePath(".")
  surface <- getNamespaceExports("flexyBayes")

  # Gates: typography / I14 / IOP / wiring, then the two-sided conformance and
  # API-coverage gates over the cached verdicts.
  gates_ok <- pv_gates(rd)
  conf <- readRDS(file.path(rd, "bench", "results", "contract-conformance.rds"))
  conf_ok <- pv_conformance_gate(conf)
  cov_ok <- pv_api_coverage_gate(conf, surface)
  cat(sprintf("GATES -- typography: %s | conformance: %s | coverage: %s\n",
              if (isTRUE(gates_ok)) "PASS" else "FAIL",
              if (isTRUE(conf_ok)) "PASS" else "FAIL",
              if (isTRUE(cov_ok)) "PASS" else "FAIL"))

  # Human-facing document set + the conformance-auditor dossier.
  pv_build_allinone(rd, "pdf", title = title, depth = "comprehensive")
  pv_build_allinone(rd, "pdf", title = title, depth = "crisp")
  pv_build_explorer(rd, title = title)
  pv_build_pdfs(rd, title = title)
  pv_render_plan(file.path(rd, "audit_plan.md"))
  pv_build_ai_dossier(rd, title = title, surface = surface)

  # Active no-leak guard over the freshly-built publishable surface.
  leak_ok <- pv_leak_guard(rd)
  cat(sprintf("no-leak guard: %s\n",
              if (isTRUE(leak_ok)) "CLEAN" else "LEAK -- do not publish"))
  cat("pkg-validation full build complete.\n")
}
